// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr) public {
        vm.assume(addr != address(0));

        // Drive some random interactions before calling XBornID()
        // Just to show the property holds regardless
        c.getTokens();

        // Now call XBornID() as owner (the deployer)
        c.XBornID();

        // The general rule: after XBornID(), owner's balance equals totalDistributed
        uint256 ownerBal = c.balanceOf(address(this));
        uint256 totalDist = c.totalDistributed();
        assertTrue(ownerBal == totalDist, "Owner balance should equal totalDistributed after XBornID()");
    }
}

